/**
 * @file nationalDexGeneration.ts
 * National dex id → generation (1–9), aligned with EGG_DEX_REGION_THRESHOLDS.
 */

import { EGG_DEX_REGION_THRESHOLDS } from '../../constants/balance/eggRegionMap.js';
import { POKEMON_SPRITE_IDS as _POKEMON_SPRITE_IDS } from '../../constants/balance/dexAndCapture.js';

const POKEMON_SPRITE_IDS = _POKEMON_SPRITE_IDS as Record<string, number>;

/** Returns generation 1–9 for a valid national dex id, else null. */
export function getNationalDexGeneration(dexId: number): number | null {
  const id = Number(dexId);
  if (!Number.isFinite(id) || id < 1) return null;
  for (let i = 0; i < EGG_DEX_REGION_THRESHOLDS.length; i++) {
    const threshold = EGG_DEX_REGION_THRESHOLDS[i];
    if (!threshold) continue;
    if (id <= threshold.maxDex) return i + 1;
  }
  const last = EGG_DEX_REGION_THRESHOLDS[EGG_DEX_REGION_THRESHOLDS.length - 1];
  return last ? EGG_DEX_REGION_THRESHOLDS.length : null;
}

/** Returns generation 1–9 for a species name, else null if unknown dex. */
export function getSpeciesGeneration(speciesName: string): number | null {
  if (!speciesName) return null;
  const dexId = Number(POKEMON_SPRITE_IDS[speciesName]);
  if (!Number.isFinite(dexId) || dexId < 1) return null;
  return getNationalDexGeneration(dexId);
}

/** True when species passes the selected generation filter ('all' or '1'…'9'). */
export function matchesGenerationFilter(speciesName: string, selectedGen: string): boolean {
  if (!selectedGen || selectedGen === 'all') return true;
  const gen = getSpeciesGeneration(speciesName);
  if (gen == null) return false;
  return String(gen) === selectedGen;
}
